"""dag_conditional — skeleton and conditional graph per GPU-submitting callback,
in the April-2026 shape_skeleton.py style, but from PostgreSQL (gpu_dags).

  fig1  backbone (LCS over all signatures) + collapsed branch blocks
  fig2  full conditional graph: the same backbone with transition counts and
        percentages, branches labelled with their absolute share

Usage: python3 -m postprocess.dag_conditional <session_id> [-o OUTDIR]
"""
from __future__ import annotations
import argparse, collections, html, json, os, re, subprocess, sys
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
import psycopg2, psycopg2.extras

DSN = os.environ.get('FISH_PG_DSN', 'host=localhost port=5432 dbname=fish user=fish password=fish')
SKEL_FILL, SKEL_EDGE, BRANCH = '#BBDEFB', '#1976D2', '#9E9E9E'
# April-2026 signature classes.  A branch is drawn in the colour of the class of
# the signature that contributes most of its invocations.
CLASS_COLOR = {'dominant': '#2E7D32', 'variant': '#9E9E9E', 'anomaly': '#D32F2F',
               'init': '#1976D2', 'warmup': '#EF6C00', 'coalesced': '#00838F',
               'shutdown': '#7B1FA2'}
CLASS_ORDER = ['dominant', 'variant', 'coalesced', 'anomaly', 'warmup', 'init', 'shutdown']
ABBR = {'cudaLaunchKernel': 'cudaLK', 'cudaMemsetAsync': 'cudaMS', 'cudaMemcpyAsync': 'cudaMC',
        'cudaMemcpy': 'cudaMC', 'cudaMemset': 'cudaMS', 'cudaMalloc': 'cudaMAL',
        'cudaMallocAsync': 'cudaMALa', 'cudaFree': 'cudaFRE', 'cudaFreeAsync': 'cudaFREa',
        'cudaStreamSynchronize': 'cudaSS', 'cudaEventRecord': 'cudaER',
        'cudaStreamWaitEvent': 'cudaSWE', 'cudaDeviceSynchronize': 'cudaDS',
        'memcpy_H2D': 'MC_H2D', 'memcpy_D2H': 'MC_D2H'}


def tok(n):
    name = (n.get('name') or '?').split('_v')[0].split('(')[0]
    return f"{n['pe']}:{ABBR.get(name, name)}"



def disp(t):
    """Display form of a token.  The full name stays in the tooltip; the LCS is
    always computed on the full token, so distinct kernels never merge."""
    pe, _, name = t.partition(':')
    n = re.sub(r'_0x[0-9a-f]{8,}', '', name).lstrip('_')
    m = re.match(r'(sm\d+)_xmma_(?:(\w+?)_)??(?:implicit_)?(gemm|conv|deconv)\b', n)
    if m:
        tile = re.search(r'tilesize(\d+x\d+x\d+)', n)
        op = m.group(2) or m.group(3)
        n = f"{m.group(1)}_{op}" + (f"_{tile.group(1)}" if tile else '') + '_trt'
    elif n.startswith('myl_'):
        n = n[:20] + '\u2026'
    if len(n) > 26:
        n = n[:25] + '\u2026'
    return f"{pe}:{n}"

def lcs(a, b):
    m = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(len(a) - 1, -1, -1):
        for j in range(len(b) - 1, -1, -1):
            m[i][j] = m[i + 1][j + 1] + 1 if a[i] == b[j] else max(m[i + 1][j], m[i][j + 1])
    out, i, j = [], 0, 0
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            out.append(a[i]); i += 1; j += 1
        elif m[i + 1][j] >= m[i][j + 1]:
            i += 1
        else:
            j += 1
    return out


def align(seq, bb):
    """Align seq against backbone bb.  Returns the insertion blocks
    {backbone index: [tokens]} and the set of backbone indices seq executed."""
    ins = collections.defaultdict(list); matched = set(); j = 0
    for t in seq:
        if j < len(bb) and t == bb[j]:
            matched.add(j); j += 1
        else:
            ins[j].append(t)
    return ins, matched


def render(dot_src, base):
    open(base + '.dot', 'w').write(dot_src)
    try:
        subprocess.check_call(['dot', '-Tsvg', base + '.dot', '-o', base + '.svg'],
                              stderr=subprocess.DEVNULL, timeout=900)
        return True
    except Exception as e:
        print(f'   dot failed: {e}'); return False



def collapse(bb, cuts, maxp=3):
    """Run-length collapse of the backbone: consecutive repeats of a period of
    1..maxp tokens become one node with a multiplicity.  Runs never span a
    position where a branch attaches, so branch anchors stay exact.
    Returns [(tokens, k, first_index)] and index -> supernode map."""
    sup, idx2, i = [], {}, 0
    while i < len(bb):
        best = (1, 1)
        for p in range(1, maxp + 1):
            if i + 2 * p > len(bb):
                break
            k = 1
            while i + (k + 1) * p <= len(bb) and bb[i + k * p:i + (k + 1) * p] == bb[i:i + p]:
                if any(c in cuts for c in range(i + 1, i + (k + 1) * p)):
                    break
                k += 1
            if k >= 2 and k * p > best[0] * best[1]:
                best = (p, k)
        p, k = best
        for j in range(i, i + p * k):
            idx2[j] = len(sup)
        sup.append((bb[i:i + p], k, i))
        i += p * k
    return sup, idx2


def classify(shapes, kept_ids, dom_id, bb, cover):
    """April's signature classes: phase decides init/warmup/coalesced, structure
    decides dominant / variant / anomaly among the productive signatures."""
    out = {}
    for i, s in enumerate(shapes):
        ph = str(s.get('phase') or 'UNKNOWN')
        if ph == 'INIT':
            out[i] = 'init'
        elif ph == 'WARMUP':
            out[i] = 'warmup'
        elif ph.startswith('COALESCED'):
            out[i] = 'coalesced'
        elif ph in ('SHUTDOWN', 'TEARDOWN'):
            out[i] = 'shutdown'
        elif i == dom_id:
            out[i] = 'dominant'
        elif bb and (cover.get(i, 0) < 0.15 * len(bb)
                     or (i not in kept_ids and cover.get(i, 0) < len(bb))):
            out[i] = 'anomaly'          # far off the skeleton, or a run that stopped inside it
        else:
            out[i] = 'variant'
    return out


def analyse(shapes, max_backbone=400):
    """Skeleton analysis.  The backbone is the LCS over the productive
    signatures only; *every* drawable signature is then aligned to it, so rare
    and INIT-phase runs still appear (coloured by their class).  Probabilities
    are conditional: the denominator at a decision is the number of invocations
    that actually reach it."""
    drawable = [s for s in shapes if s.get('nodes') and not s.get('truncated')]
    if not drawable:
        return None
    n_all = sum(int(s.get('count') or 0) for s in drawable)
    seqs = [[tok(n) for n in s['nodes']] for s in drawable]
    cnts = [int(s.get('count') or 0) for s in drawable]
    # skeleton input: productive signatures only.  INIT shapes (library/engine
    # loading) and degenerate frames (a fraction of the dominant shape) would
    # otherwise collapse the LCS to their own length.
    prod = [i for i, s in enumerate(drawable) if s.get('phase') != 'INIT'] or list(range(len(drawable)))
    dom_len = max(len(seqs[i]) for i in prod)
    kept_ids = [i for i in prod if len(seqs[i]) >= 0.5 * dom_len] or prod
    kept_ids.sort(key=lambda i: -cnts[i])
    bb = seqs[kept_ids[0]]
    for i in kept_ids[1:]:
        bb = lcs(bb, seqs[i])

    blocks = collections.Counter()                     # (pos, tokens) -> invocations
    contrib = collections.defaultdict(collections.Counter)   # (pos, tokens) -> {sig index: n}
    direct, reach = collections.Counter(), collections.Counter()
    cover, sig_ins = {}, {}
    for i, sq in enumerate(seqs):
        ins, matched = align(sq, bb)
        cover[i] = len(matched); sig_ins[i] = ins
        for pos in range(len(bb) + 1):
            here = pos in ins
            if here:
                blocks[(pos, tuple(ins[pos]))] += cnts[i]
                contrib[(pos, tuple(ins[pos]))][i] += cnts[i]
            # an invocation takes part in the decision at pos if it executed the
            # backbone token there (or the one before, at the tail) or inserted
            on = (pos in matched) if pos < len(bb) else ((len(bb) - 1) in matched)
            if here or on:
                reach[pos] += cnts[i]
                if not here:
                    direct[pos] += cnts[i]
    dom_id = kept_ids[0]
    cls = classify(drawable, set(kept_ids), dom_id, bb, cover)
    sigs = [dict(idx=i, sig=str(drawable[i].get('signature') or '')[:12], count=cnts[i],
                 n=len(seqs[i]), phase=str(drawable[i].get('phase') or '?'),
                 cls=cls[i], cover=cover[i],
                 ins=sum(len(v) for v in sig_ins[i].values())) for i in range(len(drawable))]
    sigs.sort(key=lambda d: -d['count'])
    return dict(drawable=drawable, n_all=n_all, seqs=seqs, counts=cnts, kept_ids=kept_ids,
                total=n_all, bb=bb, blocks=blocks, contrib=contrib, direct=direct, reach=reach,
                cls=cls, sigs=sigs, dom_id=dom_id,
                init=[s for s in drawable if s.get('phase') == 'INIT'],
                deg=[i for i in prod if i not in kept_ids],
                drawable_skeleton=bool(bb) and len(bb) <= max_backbone and len(kept_ids) >= 2)


def legend(classes_used):
    L = ['  subgraph cluster_legend {', '    label="Legend"; labelloc=t; labeljust=l;',
         '    fontname="Helvetica-Bold"; fontsize=9;',
         '    style="filled,rounded"; fillcolor="#FAFAFA"; color="#999999";',
         '    node [fontname="Helvetica", fontsize=7, margin="0.04,0.02"];',
         f'    lg_sk [label="skeleton (LCS backbone)", shape=box, style="filled,rounded", fillcolor="{SKEL_FILL}"];',
         '    lg_d [shape=diamond, style=filled, label="", width=0.24, height=0.22, fixedsize=true, '
         f'fillcolor="#FFFFFF", color="{SKEL_EDGE}"];',
         '    lg_dt [label="decision point\n(shares sum to the\ninvocations reaching it)", shape=plaintext, style=""];',
         '    lg_d -> lg_dt [style=invis];']
    prev = 'lg_sk'
    for c in CLASS_ORDER:
        if c in classes_used:
            L.append(f'    lg_{c} [label="branch taken by\n{c} signatures", shape=box, '
                     f'style="filled,rounded", fillcolor="{CLASS_COLOR[c]}", fontcolor="white"];')
            L.append(f'    {prev} -> lg_{c} [style=invis];'); prev = f'lg_{c}'
    L.append('  }')
    return L


def figure(bb, A, title, base, probabilities):
    """Backbone chain; wherever invocations diverge, a diamond decision node
    carries the alternatives, so a probability never labels one of several
    edges leaving the same operation node.  Branch blocks are filled with the
    colour of the signature class that contributes most of their invocations."""
    blocks, contrib, direct, reach, cls = A['blocks'], A['contrib'], A['direct'], A['reach'], A['cls']
    sigmeta = {d['idx']: d for d in A['sigs']}
    at = collections.defaultdict(list)                 # backbone position -> [(tokens, count)]
    for (pos, toks), cnt in blocks.items():
        at[pos].append((toks, cnt))
    sup, idx2 = collapse(bb, set(at))
    L = ['digraph skeleton {', '  rankdir=LR;',
         '  node [shape=box, style="filled,rounded", fontname="Helvetica", fontsize=8, margin="0.05,0.02"];',
         '  edge [fontname="Helvetica", fontsize=7];',
         f'  label="{title}"; labelloc=t; labeljust=l; fontsize=10;',
         '  graph [nodesep=0.15, ranksep=0.30];', '',
         '  subgraph cluster_skel {',
         '    label="skeleton (common to all invocations)";',
         '    style="filled,rounded"; fillcolor="#F0F7FF";',
         '    fontname="Helvetica-Bold"; fontsize=9;']
    for i, (toks, k, first) in enumerate(sup):
        body = '\n'.join(html.escape(disp(t)) for t in toks)
        rng = str(first) if k * len(toks) == 1 else f'{first}-{first + k*len(toks) - 1}'
        mult = f'\n\u00d7{k}' if k > 1 else ''
        tip = html.escape('\n'.join(t[:120] for t in toks) + (f'  (repeated {k}x)' if k > 1 else ''))[:15000]
        L.append(f'    sk{i} [label="{rng}\n{body}{mult}", fillcolor="{SKEL_FILL}", tooltip="{tip}"];')
    for pos in sorted(at):
        L.append(f'    d{pos} [shape=diamond, style=filled, label="", width=0.34, height=0.30, fixedsize=true, '
                 f'fillcolor="#FFFFFF", color="{SKEL_EDGE}", penwidth=1.5, '
                 f'tooltip="decision at backbone position {pos}: {len(at[pos])+1} alternatives, '
                 f'{reach.get(pos, 0)} invocations reach it"];')
    L.append('  }')

    def lab(n, pos, color):
        if not probabilities:
            return ''
        d = reach.get(pos, 0) or 1
        pct = 100.0 * n / d
        txt = f'{n}/{d} ({pct:.0f}%)' if pct >= 1 else f'{n}/{d}'
        return f' label="{txt}", fontcolor="{color}",'

    # branch blocks, coloured by the class of their main contributor
    bidx, used = {}, set()
    for k, ((pos, toks), cnt) in enumerate(sorted(blocks.items(), key=lambda kv: (kv[0][0], -kv[1]))):
        bidx[(pos, toks)] = k
        who = contrib[(pos, toks)].most_common()
        c = cls.get(who[0][0], 'variant') if who else 'variant'
        used.add(c)
        col = CLASS_COLOR[c]
        shown = list(toks)[:4]
        more = f'\n\u2026 +{len(toks)-4}' if len(toks) > 4 else ''
        lbl = (f'branch \u00d7{cnt}\n[{len(toks)}n]\n'
               + '\n'.join(html.escape(disp(t)) for t in shown) + more)
        head_toks = list(toks)[:60]
        tip = ('insertion block (%d tokens):\n  ' % len(toks)
               + '\n  '.join(html.escape(t[:80]) for t in head_toks)
               + (f'\n  \u2026 +{len(toks)-60} more' if len(toks) > 60 else '')
               + '\ntaken by: ' + ', '.join(f"{sigmeta[i]['sig']} [{cls[i]}] x{n}" for i, n in who[:8]))
        tip = tip[:15000]
        L.append(f'  br{k} [label="{lbl}", fillcolor="{col}", fontcolor="white", tooltip="{tip}"];')

    def decision(pos, src, dst):
        """src -> <> -> {dst, branches}; the diamond carries every probability."""
        L.append(f'  {src} -> d{pos} [color="{SKEL_EDGE}", penwidth=2, arrowhead=none];')
        L.append(f'  d{pos} -> {dst} [color="{SKEL_EDGE}", penwidth=2,{lab(direct.get(pos, 0), pos, SKEL_EDGE)}];')
        for toks, cnt in sorted(at[pos], key=lambda tc: -tc[1]):
            k = bidx[(pos, toks)]
            who = contrib[(pos, toks)].most_common()
            col = CLASS_COLOR[cls.get(who[0][0], 'variant') if who else 'variant']
            L.append(f'  d{pos} -> br{k} [color="{col}", style=dashed,{lab(cnt, pos, col)}];')
            L.append(f'  br{k} -> {dst} [color="{col}", style=dashed];')

    if 0 in at:                                        # prologue: decision before the first node
        L.append(f'  entry [shape=point, width=0.06, color="{SKEL_EDGE}"];')
        decision(0, 'entry', 'sk0')
    for i in range(len(sup) - 1):
        pos = sup[i + 1][2]
        if pos in at:
            decision(pos, f'sk{i}', f'sk{i+1}')
        else:
            L.append(f'  sk{i} -> sk{i+1} [color="{SKEL_EDGE}", penwidth=2,{lab(direct.get(pos, 0), pos, SKEL_EDGE)}];')
    if len(bb) in at:                                  # epilogue: decision after the last node
        L.append(f'  exit [shape=point, width=0.06, color="{SKEL_EDGE}"];')
        decision(len(bb), f'sk{len(sup)-1}', 'exit')
    L += legend(used)
    L.append('}')
    return render('\n'.join(L), base)


def sig_table(A, nick, path):
    """April's per-callback signature table, next to the figures."""
    bb = A['bb']
    lines = [f'{nick}', f"invocations={A['n_all']}  signatures={len(A['sigs'])}  |skeleton|={len(bb)}", '',
             f"{'sig':<14}{'class':<11}{'phase':<14}{'inv':>7}{'seq':>7}{'onskel':>8}{'ins':>7}{'skel%':>7}"]
    for d in A['sigs']:
        pct = 100.0 * d['cover'] / max(d['n'], 1)
        lines.append(f"{d['sig']:<14}{d['cls']:<11}{d['phase']:<14}{d['count']:>7}{d['n']:>7}"
                     f"{d['cover']:>8}{d['ins']:>7}{pct:>6.1f}%")
    lines += ['', 'skeleton sequence:', '  ' + ' '.join(bb[:80]) + (' …' if len(bb) > 80 else '')]
    open(path, 'w').write('\n'.join(lines) + '\n')


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('session'); ap.add_argument('--scope', default='__main__')
    ap.add_argument('-o', '--outdir', default=None); ap.add_argument('--max-backbone', type=int, default=400)
    a = ap.parse_args()
    out = a.outdir or os.path.join('paper', 'dag_gallery', a.session + '_conditional')
    os.makedirs(out, exist_ok=True)
    conn = psycopg2.connect(DSN, cursor_factory=psycopg2.extras.RealDictCursor); conn.autocommit = True
    cur = conn.cursor()
    cur.execute("""SELECT anchor_type, anchor, node, entity, n_invocations, dags FROM gpu_dags
                   WHERE session_id=%s AND scope=%s ORDER BY n_invocations DESC""", (a.session, a.scope))
    blocks_html = []
    for r in cur.fetchall():
        shapes = r['dags'] if isinstance(r['dags'], list) else json.loads(r['dags'])
        A = analyse(shapes, a.max_backbone)
        if not A or not A['drawable_skeleton']:
            continue
        bb, n_all = A['bb'], A['n_all']
        by_cls = collections.Counter(d['cls'] for d in A['sigs'])
        nick = (f"{r['node']} ← {r['entity']}" if r['entity'] else r['node']) or f"thread {r['anchor']}"
        tag = f"{r['anchor_type']}_{str(r['anchor']).replace('0x','').lower()}"
        base = (f"{nick} — {n_all} inv, {len(A['sigs'])} sigs "
                f"({', '.join(f'{n} {c}' for c, n in by_cls.most_common())}), "
                f"|skel|={len(bb)} over {len(A['kept_ids'])} productive sigs")
        print(f"{nick}: {len(A['sigs'])} signatures, backbone {len(bb)}, "
              f"{len(A['blocks'])} branch block(s), classes {dict(by_cls)}")
        f1 = figure(bb, A, base + ' · fig1: backbone + collapsed branches',
                    os.path.join(out, f'{tag}_fig1'), probabilities=False)
        f2 = figure(bb, A, base + ' · fig2: conditional graph (decision nodes, conditional shares)',
                    os.path.join(out, f'{tag}_fig2'), probabilities=True)
        sig_table(A, nick, os.path.join(out, f'{tag}.txt'))
        figs = ''.join(
            f'<div class="fig"><div class="cap">{html.escape(c)} · <a href="{tag}_fig{i}.svg">svg</a></div>'
            f'<a href="{tag}_fig{i}.svg" target="_blank"><img src="{tag}_fig{i}.svg" loading="lazy"></a></div>'
            for i, c, ok in ((1, 'fig1: backbone + collapsed branches', f1),
                             (2, 'fig2: conditional graph with probabilities', f2)) if ok)
        chips = ''.join(f'<span style="background:{CLASS_COLOR[c]};color:#fff;border-radius:3px;'
                        f'padding:1px 6px;margin-right:4px;font-size:.8em">{c} {n}</span>'
                        for c, n in by_cls.most_common())
        blocks_html.append(f'<div class="cb"><h2>{html.escape(nick)}</h2><div class="meta">'
                           f'{r["n_invocations"]} invocations · {len(A["sigs"])} signatures · '
                           f'backbone {len(bb)} tokens · {len(A["blocks"])} branch blocks · '
                           f'<a href="{tag}.txt">signature table</a></div><div style="margin:.3em 0">{chips}</div>'
                           f'{figs}</div>')
    css = ("body{font-family:system-ui,sans-serif;max-width:1600px;margin:1em auto;color:#222}"
           "h1{font-size:1.4em}h2{font-size:1.05em;color:#1a5490;margin:.2em 0}"
           ".cb{border:1px solid #ddd;border-radius:6px;padding:.8em 1em;margin-bottom:1em;background:#fafafa}"
           ".meta{color:#666;font-size:.85em;margin-bottom:.6em}.fig{margin:.6em 0}"
           ".fig img{max-width:100%;border:1px solid #ccc;border-radius:4px;background:#fff}"
           ".cap{font-size:.82em;color:#444;margin:.2em 0}a{color:#1a5490}")
    open(os.path.join(out, 'index.html'), 'w').write(
        f'<!DOCTYPE html><html><head><meta charset="utf-8"><title>FISH conditional graphs — {a.session}</title>'
        f'<style>{css}</style></head><body><h1>Skeleton and conditional graph — {a.session}</h1>'
        f'<p class="meta">Backbone = longest common subsequence over the productive signatures of a callback; '
        f'grey/coloured blocks are the insertions of individual signatures, filled with the class of the '
        f'signature that contributes most of their invocations.  Where invocations diverge, a diamond '
        f'decision node carries the alternatives: its outgoing shares are conditional on reaching it.</p>'
        + ''.join(blocks_html) + '</body></html>')
    print(f'[conditional] {os.path.join(out, "index.html")}')


if __name__ == '__main__':
    main()
